#include <iostream>
#include <string>

bool isMatch(const std::string& s, const std::string& p) {
    int m = s.size(), n = p.size();
    bool[][] dp = new bool[m + 1][n + 1];

    for (int i = 0; i <= m; ++i)
        dp[i][0] = true;
    for (int j = 0; j <= n; ++j) {
        if (p[j] == '.') {
            for (int i = 0; i <= m; ++i) {
                dp[i][j + 1] = dp[i][j];
            }
        } else if (p[j] == '*') {
            for (int i = 0; i <= m; ++i)
                for (int j2 = 0; j2 <= n && j2 - j < i; ++j2) {
                    dp[i + 1][j2 + 1] = dp[i][j2];
                    if (p[j2] == '.') {
                        dp[i + 1][j2 + 1] = dp[i + 1][j2 + 1];
                    } else if (p[j2] != s[i]) {
                        break;
                    }
                }
            for (int i = 0; i <= m; ++i) {
                dp[i + 1][0] = true;
            }
        }
    }

    return dp[m][n];
}

int main() {
    std::cout << std::boolalpha << isMatch("aa", "a") << std::endl; // false
    std::cout << std::boolalpha << isMatch("aa", "a*") << std::endl; // true
    std::cout << std::boolalpha << isMatch("ab", ".*") << std::endl; // true
    return 0;
}
```

