        root = new Node{value, nullptr, nullptr};
        _insert_recursive(root, value);
    }

    void _insert_recursive(Node*& node, int value) {
        if (value < node->value) {
            if (node->left == nullptr) {
                node->left = new Node{value, nullptr, nullptr};
            } else {
                _insert_recursive(node->left, value);
            }
        } else {
